<?php
require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; require_login(); $pdo=dogvive_db();
$id=(int)($_GET['id']??0); $q=$pdo->prepare('SELECT * FROM mascota WHERE id_mascota=? AND id_usuario=?'); $q->execute([$id,dogvive_user_id()]); $pet=$q->fetch();
if(!$pet){ http_response_code(404); start_app('Mascota no encontrada','mascotas'); echo '<div class="card"><h2>No se encontró esa mascota</h2><p>Solo puedes consultar expedientes de tus propias mascotas.</p>'.btn('Volver a mis mascotas',page_url('mascotas')).'</div>'; end_app(); exit; }
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['eliminar_vacuna'])){ $del=$pdo->prepare('DELETE FROM vacuna WHERE id_vacuna=? AND id_mascota=?'); $del->execute([(int)$_POST['eliminar_vacuna'],$id]); dogvive_flash('success',$del->rowCount()?'Vacuna eliminada del carnet.':'No se pudo eliminar esa vacuna.'); header('Location: '.base_url().'/mascota-perfil.php?id='.$id); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){
 try { $name=trim((string)($_POST['vacuna']??'')); $date=(string)($_POST['fecha_aplicacion']??''); $next=trim((string)($_POST['proxima_dosis']??'')); if(!$name||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)) throw new RuntimeException('Indica el nombre de la vacuna y la fecha de aplicación.'); $doc=dogvive_upload($_FILES['documento_vacuna']??[], 'vacunas', ['image/jpeg','image/png','image/webp','application/pdf']); $ins=$pdo->prepare('INSERT INTO vacuna (id_mascota,Nombre,Fecha_aplicacion,Proxima_dosis,Veterinaria,Lote,Documento_archivo,Observaciones) VALUES (?,?,?,?,?,?,?,?)'); $ins->execute([$id,$name,$date,$next?:null,trim((string)($_POST['veterinaria']??'')),trim((string)($_POST['lote']??'')),$doc,trim((string)($_POST['observaciones']??''))]); dogvive_flash('success','Vacuna agregada al carnet.'); } catch(Throwable $e){ dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la vacuna.'); } header('Location: '.base_url().'/mascota-perfil.php?id='.$id); exit;
}
$success=dogvive_flash('success'); $error=dogvive_flash('error'); $v=$pdo->prepare('SELECT * FROM vacuna WHERE id_mascota=? ORDER BY Fecha_aplicacion DESC'); $v->execute([$id]); $vaccines=$v->fetchAll();
start_app('Expediente de mascota','mascotas'); page_wrap_start('Expediente de '.(string)$pet['Nombre'],'Información general, salud e historial de vacunas.');
if($success) echo '<div class="notice">'.e($success).'</div>'; if($error) echo '<div class="error-box">'.e($error).'</div>';
echo '<div class="detail-grid"><div class="card">'; if($pet['Foto']) echo '<img class="profile-photo" src="'.e(base_url().'/'.$pet['Foto']).'" alt="Mascota">'; else echo '<div class="avatar" style="width:90px;height:90px">🐾</div>'; echo '<h2>'.e($pet['Nombre']).'</h2><p class="muted">'.e($pet['Especie'].' · '.$pet['Raza']).'</p><div class="info-list">'; foreach(['Edad'=>'Edad','Sexo'=>'Sexo','Peso'=>'Peso','Color'=>'Color','Microchip'=>'Microchip','Alergias'=>'Alergias','Condiciones_medicas'=>'Condiciones médicas','Contacto_veterinario'=>'Veterinario','Observaciones'=>'Observaciones'] as $label=>$key){if(($pet[$key]??'')!=='') echo '<div><span>'.e($label).'</span><strong>'.e((string)$pet[$key]).'</strong></div>';} echo '</div></div><div class="card"><h3>💉 Carnet de vacunación</h3><p class="muted">Guarda las vacunas aplicadas y las próximas dosis. Confirma el calendario con tu veterinario.</p>';
if(!$vaccines) echo '<div class="notice">Todavía no hay vacunas registradas.</div>'; else {echo '<div class="booking-list">'; foreach($vaccines as $vac){echo '<div class="booking-item"><div class="grow"><strong>'.e($vac['Nombre']).'</strong><small class="muted">Aplicada: '.e($vac['Fecha_aplicacion']).'</small><small class="muted">Próxima dosis: '.e($vac['Proxima_dosis']?:'No indicada').'</small>'; if($vac['Veterinaria']) echo '<small class="muted">'.e($vac['Veterinaria']).'</small>'; if($vac['Documento_archivo']) echo '<a target="_blank" rel="noopener" href="'.e(base_url().'/'.$vac['Documento_archivo']).'">Ver comprobante</a>'; echo '<form method="post" onsubmit="return confirm(\'¿Eliminar este registro de vacuna?\')"><button class="btn btn-secondary" type="submit" name="eliminar_vacuna" value="'.(int)$vac['id_vacuna'].'">Eliminar registro</button></form>'; echo '</div></div>';} echo '</div>'; }
echo '<hr><h3>Agregar vacuna</h3><form method="post" enctype="multipart/form-data"><label>Nombre de la vacuna<input name="vacuna" maxlength="120" required placeholder="Ej. Rabia"></label><div class="form-grid"><label>Fecha de aplicación<input type="date" name="fecha_aplicacion" max="'.date('Y-m-d').'" required></label><label>Próxima dosis<input type="date" name="proxima_dosis" min="'.date('Y-m-d').'"></label></div><div class="form-grid"><label>Veterinaria<input name="veterinaria"></label><label>Lote (opcional)<input name="lote"></label></div><label>Comprobante / foto del carnet<input type="file" name="documento_vacuna" accept="image/jpeg,image/png,image/webp,application/pdf"></label><label>Observaciones<textarea name="observaciones" rows="2"></textarea></label><button class="btn btn-primary full" type="submit">Guardar en el carnet</button></form></div></div>';
page_wrap_end(); end_app();
